import sys, re
LANG = (sys.argv[1] if len(sys.argv) > 1 else 'HU').upper()

def _items_hu(n, ns, g, a, cs, nth, disc, eros):
    return [
        ('Lefedettség', f'{n} termék {ns} áruházból: német–osztrák piac {g[0]}, Benelux {g[1]}, környező országok {g[2]}, Balkán {g[3]} termék. A Balkán-körben SI, HR, RS, RO és BG 13 áruháza szerepel; Bosznia-Hercegovinából nem jött termék (az Emmezeta és a Lesnina BA oldala nem nyílt meg, a JYSK BA-nál nincs 600 € feletti kanapé).', 'Pótolni: BA áruházai, valamint kis áruházak – a Balkán-körben nincs kis áruház, a környező országokban az arányuk 1/3 alatt maradt.'),
        ('Piaccsoportok árszintje', f'Átlagár: német–osztrák piac {a[0]} €, Benelux {a[1]} €, környező országok {a[2]} €, Balkán {a[3]} €. Országonként: {cs}.', 'A Balkán a legolcsóbb csoport; Bulgária (~856 €) a legolcsóbb ország. A 600 € alatti termékek kimaradtak, ezért a valós szintkülönbség még nagyobb.'),
        ('Azonos modellek', 'IKEA: a Jättebo 2,5 sz. + heverő SI 1 670 €, HU 1 878 €, RS 1 547 €, RO 1 533 €, SK 1 520 €; a Söderhamn 3 sz. SI 780 €, RO 636 €; a Vimle 5 sz. heverővel HU 1 855 €, RS 1 632 €, SI 1 510 €. XXXLutz-csoport: Carryhome, Xora, Cantus modellek CZ–SK; a Mömax Mason RO-ban 1 309 €, HU-ban 1 097 €.', 'Az IKEA és az XXXLutz-csoport országonkénti árazása a legtisztább összevetés – minden futásban követni kell.'),
        ('Áthúzott és kártyás árak', f'{nth} terméknél van áthúzott ár, átlagosan {disc}%-os kedvezménnyel; {eros} terméknél „erős áthúzás”. A Balkánon a Videnov és a Mobexpert szinte minden termékét 30–45%-kal áthúzza (Black Friday); az Emmezeta klubára és a Forma Ideale hűségára külön oszlopban szerepel.', 'Az áthúzott ár inkább marketing; a piaci összevetéshez a tényleges ár a mérvadó, a kártyás ár csak tájékoztató.'),
        ('Árszint áruházanként', 'Balkán, legolcsóbb átlag: Videnov (BG) ~790 €, Forma Ideale (RS) ~895 €, Mömax SI ~965 €. Legdrágább: IKEA HR ~1 810 €, IKEA SI ~1 670 €, IKEA RS ~1 535 €.', 'A Balkánon az IKEA a felső szegmens; a helyi láncok (Videnov, Forma Ideale, Mobexpert) olcsóbbak.'),
        ('Típusok', 'Mind a négy piacon a sarokülő a leggyakoribb (a Balkánon 96 a 107-ből). Franciaágy 600 € felett a Balkánon a Lesnina XXXL SI-nél és a Mobexpertnél; fotel 600 € felett nem volt (csak kerti fotel és piactéri ajánlat).', 'PL/CZ/SK/HU-ban és a Balkánon külön fotel- és franciaágy-keresés kell 600 € felett.'),
        ('Adathiány', 'A Balkán-körben áruházanként a 3 legnépszerűbb termékoldalt megnyitottuk: szövet 45, láb 30 terméknél azonosítható. Szövet- és lábfotó még nincs.', 'A következő körben a termékoldali galériából a szövet- és lábközeli fotót is menteni kell.'),
    ]

def _items_en(n, ns, g, a, cs, nth, disc, eros):
    return [
        ('Coverage', f'{n} products from {ns} retailers: German–Austrian market {g[0]}, Benelux {g[1]}, neighbouring countries {g[2]}, Balkans {g[3]} products. The Balkan round covers 13 retailers in SI, HR, RS, RO and BG; no products came from Bosnia and Herzegovina (the Emmezeta and Lesnina BA sites did not open, JYSK BA has no sofa above €600).', 'To add: retailers in BA and small retailers – the Balkan round has none, and in the neighbouring countries their share stayed below 1/3.'),
        ('Price level by market group', f'Average price: German–Austrian market €{a[0]}, Benelux €{a[1]}, neighbouring countries €{a[2]}, Balkans €{a[3]}. By country: {cs}.', 'The Balkans are the cheapest group; Bulgaria (~€856) is the cheapest country. Products below €600 were left out, so the real gap is even larger.'),
        ('Identical models', 'IKEA: Jättebo 2.5-seat + chaise SI €1,670, HU €1,878, RS €1,547, RO €1,533, SK €1,520; Söderhamn 3-seat SI €780, RO €636; Vimle 5-seat with chaise HU €1,855, RS €1,632, SI €1,510. XXXLutz group: Carryhome, Xora and Cantus models in CZ and SK; Mömax Mason €1,309 in RO, €1,097 in HU.', 'Country pricing of IKEA and the XXXLutz group is the cleanest comparison – track it in every run.'),
        ('Crossed-out and card prices', f'{nth} products show a crossed-out price, with an average discount of {disc}%; {eros} products have a “strong markdown”. In the Balkans Videnov and Mobexpert mark down almost every product by 30–45% (Black Friday); Emmezeta club prices and Forma Ideale loyalty prices are shown in a separate column.', 'The crossed-out price is mostly marketing; the actual selling price is what counts, the card price is for information only.'),
        ('Price level by retailer', 'Balkans, cheapest average: Videnov (BG) ~€790, Forma Ideale (RS) ~€895, Mömax SI ~€965. Most expensive: IKEA HR ~€1,810, IKEA SI ~€1,670, IKEA RS ~€1,535.', 'In the Balkans IKEA is the upper segment; local chains (Videnov, Forma Ideale, Mobexpert) are cheaper.'),
        ('Product types', 'Corner sofas are the most common type in all four markets (96 of 107 in the Balkans). Double beds above €600 in the Balkans at Lesnina XXXL SI and Mobexpert; no armchairs above €600 (only garden chairs and marketplace offers).', 'A separate armchair and double-bed search above €600 is needed for PL/CZ/SK/HU and the Balkans.'),
        ('Data gaps', 'In the Balkan round the 3 most popular product pages per retailer were opened: the fabric can be identified for 45 and the legs for 30 products. No fabric or leg close-ups yet.', 'In the next round save the fabric and leg close-ups from the product-page gallery as well.'),
    ]

def _items_de(n, ns, g, a, cs, nth, disc, eros):
    return [
        ('Abdeckung', f'{n} Produkte aus {ns} Möbelhäusern: deutsch-österreichischer Markt {g[0]}, Benelux {g[1]}, Nachbarländer {g[2]}, Balkan {g[3]} Produkte. Der Balkan-Durchlauf umfasst 13 Möbelhäuser in SI, HR, RS, RO und BG; aus Bosnien und Herzegowina kamen keine Produkte (die Seiten von Emmezeta und Lesnina BA öffneten sich nicht, JYSK BA hat kein Sofa über 600 €).', 'Ergänzen: Händler in BA und kleine Händler – im Balkan-Durchlauf gibt es keinen, in den Nachbarländern blieb ihr Anteil unter 1/3.'),
        ('Preisniveau nach Marktgruppe', f'Durchschnittspreis: deutsch-österreichischer Markt {a[0]} €, Benelux {a[1]} €, Nachbarländer {a[2]} €, Balkan {a[3]} €. Nach Ländern: {cs}.', 'Der Balkan ist die günstigste Gruppe; Bulgarien (~856 €) das günstigste Land. Produkte unter 600 € fielen heraus, der tatsächliche Abstand ist also noch größer.'),
        ('Identische Modelle', 'IKEA: Jättebo 2,5-Sitzer + Récamiere SI 1.670 €, HU 1.878 €, RS 1.547 €, RO 1.533 €, SK 1.520 €; Söderhamn 3-Sitzer SI 780 €, RO 636 €; Vimle 5-Sitzer mit Récamiere HU 1.855 €, RS 1.632 €, SI 1.510 €. XXXLutz-Gruppe: Carryhome-, Xora- und Cantus-Modelle in CZ und SK; Mömax Mason in RO 1.309 €, in HU 1.097 €.', 'Die Länderpreise von IKEA und der XXXLutz-Gruppe sind der sauberste Vergleich – in jedem Durchlauf verfolgen.'),
        ('Streich- und Kartenpreise', f'{nth} Produkte haben einen Streichpreis, im Durchschnitt {disc} % Rabatt; bei {eros} Produkten „starke Streichung“. Auf dem Balkan streichen Videnov und Mobexpert fast jedes Produkt um 30–45 % (Black Friday); Emmezeta-Clubpreise und Forma-Ideale-Treuepreise stehen in einer eigenen Spalte.', 'Der Streichpreis ist eher Marketing; maßgeblich ist der tatsächliche Verkaufspreis, der Kartenpreis dient nur zur Information.'),
        ('Preisniveau nach Möbelhaus', 'Balkan, günstigster Durchschnitt: Videnov (BG) ~790 €, Forma Ideale (RS) ~895 €, Mömax SI ~965 €. Teuerster: IKEA HR ~1.810 €, IKEA SI ~1.670 €, IKEA RS ~1.535 €.', 'Auf dem Balkan ist IKEA das obere Segment; lokale Ketten (Videnov, Forma Ideale, Mobexpert) sind günstiger.'),
        ('Produkttypen', 'In allen vier Märkten ist das Ecksofa am häufigsten (auf dem Balkan 96 von 107). Doppelbetten über 600 € auf dem Balkan bei Lesnina XXXL SI und Mobexpert; keine Sessel über 600 € (nur Gartensessel und Marktplatzangebote).', 'Für PL/CZ/SK/HU und den Balkan ist eine eigene Sessel- und Doppelbettsuche über 600 € nötig.'),
        ('Datenlücken', 'Im Balkan-Durchlauf wurden je Möbelhaus die 3 beliebtesten Produktseiten geöffnet: Bezug bei 45, Füße bei 30 Produkten erkennbar. Noch keine Stoff- oder Fußfotos.', 'Im nächsten Durchlauf auch die Stoff- und Fußnahaufnahmen aus der Produktgalerie speichern.'),
    ]

